extra_methods.body:
if (targetTag != _targetType) return;
OnInteract();
InstantiateVFX(hitPoint, "fire", ref _vfxFireList);
InstantiateVFX(hitPoint, "smoke", ref _vfxSmokeList);

if (list == null) return;
for (int i = 0; i < list.Count; i++)
{
    ParticleSystem ps = Instantiate(list[i], pos, Quaternion.identity);
    ps.Play();
}
// Note: In a real implementation with List<ParticleSystem> as field, we would need to manage instantiation differently or use a different structure. This method assumes the field holds prefabs or handles logic outside standard Unity component lifecycle for this specific constraint set.

_smokeTrail1 = Instantiate(_smokeTrail1, impactPos, Quaternion.identity);
_smokeTrail1.Play();
_fire1 = Instantiate(_fire1, impactPos, Quaternion.identity);
_fire1.Play();

_fogDensity = Mathf.Max(0.01f, _fogDensity * (1.0f + intensity));
ambientIntensity += intensity * 2.5f;
if (_smokeIntensity > 1.5f) { ambientGround = new Color(0.3f, 0.3f, 0.4f); } else { ambientGround = new Color(0.6f, 0.7f, 0.8f); }

_fogDensity = _smokeIntensity * 0.02f;
ambientIntensity = 1.5f;
ambientGround = new Color(0.6f, 0.7f, 0.8f);
ambientSky = new Color(0.4f, 0.6f, 0.9f);

GameObject enemyPrefab = Get(difficultyTier);
if (enemyPrefab == null) return null;

// Attempt to spawn slightly offset from clouds if near a cloud layer for visual variety
Vector3 spawnPos = position;
if (_cloudLayer != null && Vector3.Distance(position, _cloudLayer.transform.position) < 10f)
{
    // Simple logic: ensure we don't spawn inside the cloud volume by nudging up/down randomly
    float offset = Random.Range(-5f, 5f);
    spawnPos += new Vector3(0, offset, 0);
}

GameObject enemy = Instantiate(enemyPrefab, position, rotation);
return enemy;

if (!_playing) return;
if (TryStartDialog()) {
    _targetTag = "Player";
    _dialogueText = "Enemy detected. Prepare for interception.";
}

input.update_extra:
if (_cooldown > 0f) _cooldown -= Time.deltaTime;
if (_targetEnemyPlane != null && _targetEnemyPlane.activeInHierarchy) {
    var target = _targetEnemyPlane.GetComponent<BTNodeDef>();
}
